import type {
  ContractChangedPayload,
  Fact,
  GatePayload,
  PinPayload,
  ScaffoldRecord,
  SyncPayload,
} from '../domain/types'
import { urn } from '../domain/urn'
import { FP_ORDER_CONFIRMED, FP_ORDER_CONFIRMED_OLD } from './topologies'

// The ledger: what changed, when, by whom. Each fact's payload is what the
// emitting source already records — GitOps Deploy-* trailers for pins and
// promotes, ArgoCD for syncs, the scaffold record for creations.

let seq = 0
function fact<P>(
  kind: Fact['kind'],
  urnValue: string,
  observedAt: string,
  source: Fact['source'],
  payload: P,
): Fact<P> {
  seq += 1
  return { id: `ledger-${String(seq).padStart(3, '0')}`, urn: urnValue, kind, observedAt, source, payload }
}

const scaffold = (
  domain: string,
  system: string,
  component: string,
  at: string,
  record: ScaffoldRecord,
) =>
  fact<ScaffoldRecord>('component.scaffolded', urn('acme', domain, system, component), at, {
    command: 'int create',
    version: '0.7.0',
    actor: 'jonas',
  }, record)

const pin = (
  domain: string,
  system: string,
  component: string,
  at: string,
  actor: string,
  payload: PinPayload,
  promoted = false,
) =>
  fact<PinPayload>(promoted ? 'env.promoted' : 'env.pinned', urn('acme', domain, system, component), at, {
    command: promoted ? 'deploy promote' : 'deploy pin',
    version: '0.9.2',
    actor,
  }, payload)

const sync = (domain: string, system: string, component: string, at: string, payload: SyncPayload) =>
  fact<SyncPayload>('env.synced', urn('acme', domain, system, component), at, {
    command: 'argocd (observed)',
    version: '0.9.2',
    actor: 'argocd',
  }, payload)

export const ledgerFacts: Array<Fact> = [
  // --- estate scaffolding, spring 2026 ---
  scaffold('commerce', 'erp-orders', 'order-extract', '2026-04-02T09:00:00Z', { template: 'extractor', version: '0.7.0', blockKind: 'extractor', dataFlow: 'in' }),
  scaffold('commerce', 'erp-orders', 'order-enrich', '2026-04-02T09:20:00Z', { template: 'transactional', version: '0.7.0', blockKind: 'transactionalIntegration' }),
  scaffold('commerce', 'webshop-sync', 'order-loader', '2026-04-10T13:00:00Z', { template: 'loader', version: '0.7.0', blockKind: 'loader', dataFlow: 'out' }),
  scaffold('commerce', 'webshop-sync', 'stock-extract', '2026-04-10T13:15:00Z', { template: 'extractor', version: '0.7.0', blockKind: 'extractor', dataFlow: 'in' }),
  scaffold('commerce', 'webshop-sync', 'stock-loader', '2026-04-10T13:30:00Z', { template: 'loader', version: '0.7.0', blockKind: 'loader', dataFlow: 'out' }),
  scaffold('finance', 'invoicing', 'invoice-builder', '2026-05-05T10:00:00Z', { template: 'transactional', version: '0.7.1', blockKind: 'transactionalIntegration' }),
  scaffold('finance', 'invoicing', 'invoice-loader', '2026-05-05T10:20:00Z', { template: 'loader', version: '0.7.1', blockKind: 'loader', dataFlow: 'out' }),
  scaffold('finance', 'invoicing', 'posting-export', '2026-05-12T11:00:00Z', { template: 'loader', version: '0.7.1', blockKind: 'loader', dataFlow: 'out' }),

  // --- the OrderConfirmed v2 arc, late July ---
  fact<ContractChangedPayload>(
    'contract.changed',
    urn('acme', 'commerce', 'erp-orders'),
    '2026-07-28T12:12:00Z',
    { command: 'graph (host verb)', version: '0.9.2', actor: 'ci' },
    {
      shortName: 'OrderConfirmed',
      from: FP_ORDER_CONFIRMED_OLD,
      to: FP_ORDER_CONFIRMED,
      release: '2.4.0',
      component: 'order-enrich',
    },
