import type { DiagramBinding, KnowledgeDoc } from '../domain/types'
import { urn } from '../domain/urn'

// Knowledge follows the OKF v0.2 pilot profile from intropy-cli/catalog/:
// typed docs with commands[] binding them to the verbs they explain.

export const knowledgeDocs: KnowledgeDoc[] = [
  {
    slug: 'releases-and-image-digests',
    type: 'Intropy Concept',
    title: 'Releases and image digests',
    description: 'Why environments pin digests, what a release manifest promises, and what "consistent" means.',
    tags: ['release', 'deploy', 'digest'],
    status: 'verified',
    commands: ['intropy release create', 'intropy deploy pin', 'intropy deploy status'],
    body: [
      'A release is an immutable manifest in the OCI registry: a version, the source commit it was built from, and one digest per image. Editing a release is not possible — a correction is a new version.',
      'An environment never runs "a release"; it pins digests. The release annotation on an overlay records intent, the digest records fact. deploy status compares digests, which is why its consistent flag is trustworthy: every onboarded environment pins the identical digest for every image, or it does not.',
      'Promotion copies the digests one environment runs into the next environment in the promotion graph. prod running the bits staging tested is therefore checkable, not aspirational.',
    ],
  },
  {
    slug: 'deployment-troubleshooting',
    type: 'Intropy Playbook',
    title: 'Deployment troubleshooting',
    description: 'Symptom-first triage for environment rows that disagree, wait, or cannot be read.',
    tags: ['deploy', 'argocd', 'gitops'],
    status: 'verified',
    commands: ['intropy deploy status', 'intropy deploy diff', 'intropy deploy sync'],
    body: [
      'Start from the symptom, not the tool. Every row below names the boundary the evidence lives on and the one safe next action. Nothing here mutates state.',
    ],
    triage: [
      {
        symptom: 'environments run different releases (consistent: false)',
        boundary: 'GitOps overlays',
        evidence: 'deploy status rows: which environment pins which digest',
        nextAction: 'intropy deploy diff <component> --env <behind-env>',
      },
      {
        symptom: 'a manual environment shows pending',
        boundary: 'ArgoCD sync gate',
        evidence: 'committed overlay change, syncedRevision older than revision',
        nextAction: 'intropy deploy sync <component> --env prod (after review)',
      },
      {
        symptom: 'sync and health columns are absent',
        boundary: 'ArgoCD reachability',
        evidence: 'diagnostics name the environment that could not be read',
        nextAction: 'read again before concluding anything — absence is not failure',
      },
      {
        symptom: 'an environment row is greyed out',
        boundary: 'GitOps onboarding',
        evidence: 'onboarded: false with a reason',
        nextAction: 'intropy deploy init <component>',
      },
    ],
  },
]

// What the diagramming tool's reconciler last reported about shape→URN
// bindings. One live, one stale, one never bound — the three drift states.
export const diagramBindings: DiagramBinding[] = [
  {
    shape: 'erp-orders',
    diagram: 'order-flow overview',
    urn: urn('acme', 'commerce', 'erp-orders'),
    state: 'live',
  },
  {
    shape: 'ftp-legacy connector',
    diagram: 'order-flow overview',
    urn: urn('acme', 'commerce', 'webshop-sync', 'ftp-legacy'),
    state: 'stale',
    note: 'bound URN no longer appears in any declared topology',
  },
  {
    shape: 'crm-sync',
    diagram: 'order-flow overview',
    state: 'unbound',
    note: 'drawn in the diagram, not yet built — planned work or drift',
  },
]

export const monitoringBase = 'https://monitor.acme.example/d/intropy-flow'

/** Deep link into the monitoring tool, pre-scoped the way the outbound
 *  integration promises: URN identity as the label scheme. */
export function monitoringLink(system: string, component?: string, environment = 'prod'): string {
  const params = new URLSearchParams({ system, env: environment })
  if (component) params.set('component', component)
  return `${monitoringBase}?${params.toString()}`
}

