// FactSource is the seam between the pages and wherever facts come from.
// The PoC folds fixtures in memory; a real ingestion backend replaces this
// interface's implementation without touching a page.

import type {
  Contract,
  DiagramBinding,
  EnvironmentStatus,
  Fact,
  JsonSchema,
  KnowledgeDoc,
  ReleaseManifest,
  StatusResult,
  Topology,
  TopologyConnector,
} from '../domain/types'

export interface EstateComponentRow {
  urn: string
  component: string
  blockKind?: string
  status: StatusResult
  observedAt: string
}

export interface EstateSystemRow {
  urn: string
  domain: string
  system: string
  components: EstateComponentRow[]
  /** Every component's environments agree on digests. */
  consistent: boolean
  pendingGates: number
}

export interface EstateView {
  customer: string
  readAt: string
  domains: Array<{ domain: string; systems: EstateSystemRow[] }>
  totals: { systems: number; components: number; inconsistent: number; pendingGates: number }
}

export interface ContractAlias {
  system: string
  domain: string
  name: string
  publishers: string[]
  subscribers: string[]
}

export interface ContractDrift {
  system: string
  component: string
  environment: string
  pinnedRelease: string
  runsFingerprint: string
  currentSinceRelease: string
}

export interface ContractRow {
  fingerprint: string
  shortName: string
  mediaType?: string
  schema?: JsonSchema
  aliases: ContractAlias[]
  systems: string[]
  domains: string[]
  componentCount: number
  drift: ContractDrift[]
  observedAt: string
}

export interface SystemView {
  urn: string
  domain: string
  system: string
  topology: Topology
  observedAt: string
  statuses: EstateComponentRow[]
  releases: Array<Fact<ReleaseManifest>>
}

export interface ConnectorRow {
  externalSystem: string
  connectors: Array<{
    system: string
    domain: string
    connector: TopologyConnector
  }>
}

export interface MapNode {
  id: string
  label: string
  kind: 'system' | 'external'
  domain?: string
  consistent?: boolean
  pendingGates?: number
  drift?: string
}

export interface MapEdge {
  id: string
  from: string
  to: string
  provenance: 'declared' | 'mediated' | 'derived'
  label: string
}

export interface MapGraph {
  nodes: MapNode[]
  edges: MapEdge[]
  bindings: DiagramBinding[]
}

export interface LedgerFilter {
  kind?: string
  system?: string
}

export interface FactSource {
  estate(): Promise<EstateView>
  contracts(): Promise<ContractRow[]>
  contract(fingerprint: string): Promise<ContractRow | undefined>
  system(domain: string, system: string): Promise<SystemView | undefined>
  connectors(): Promise<ConnectorRow[]>
  map(): Promise<MapGraph>
  ledger(filter?: LedgerFilter): Promise<Fact[]>
  knowledge(): Promise<KnowledgeDoc[]>
}

export type { Contract, EnvironmentStatus, Fact, KnowledgeDoc, StatusResult, Topology }

