  color: var(--muted);
  font-weight: 500;
}

.rail nav a:hover {
  color: var(--ink);
  text-decoration: none;
  background: rgba(42, 122, 104, 0.06);
}

.rail nav a.active {
  color: var(--verdigris-deep);
  background: var(--verdigris-bg);
}

.rail-foot {
  margin-top: auto;
  font-size: 11.5px;
  color: var(--faint);
  line-height: 1.7;
}

.customer-chip {
  display: inline-block;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--verdigris-deep);
  background: var(--verdigris-bg);
  border: 1px solid rgba(42, 122, 104, 0.25);
  border-radius: 999px;
  padding: 1px 10px;
  margin-bottom: 6px;
}

main.content {
  padding: 40px 48px 80px;
  max-width: 1120px;
  min-width: 0;
}

/* --- page headers --- */

.page-head {
  margin-bottom: 28px;
}

.eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--faint);
  margin-bottom: 6px;
}

h1 {
  font-family: var(--display);
  font-weight: 480;
  font-variation-settings: 'SOFT' 40;
  font-size: 32px;
  line-height: 1.15;
  margin: 0 0 8px;
}

h2 {
  font-family: var(--display);
  font-weight: 520;
  font-size: 20px;
  margin: 36px 0 12px;
}

h3 {
  font-size: 14px;
  font-weight: 650;
  margin: 0 0 8px;
}

.lede {
  color: var(--muted);
  max-width: 62ch;
  margin: 0;
}

/* --- cards, tables, chips --- */

.card {
  background: var(--card);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  padding: 18px 20px;
}

.board {
  width: 100%;
  border-collapse: collapse;
  background: var(--card);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  overflow: hidden;
}

.board th {
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
  padding: 10px 14px;
  border-bottom: 1px solid var(--hairline);
}

.board td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--hairline);
  vertical-align: top;
}

.board tr:last-child td {
  border-bottom: none;
}

.board tbody tr:hover {
  background: rgba(42, 122, 104, 0.035);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 550;
  border-radius: 999px;
  padding: 1px 9px;
  border: 1px solid var(--hairline);
  color: var(--muted);
  background: var(--card);
  white-space: nowrap;
}

.chip.ok {
  color: var(--verdigris-deep);
  background: var(--verdigris-bg);
  border-color: rgba(42, 122, 104, 0.25);
}

.chip.warn {
  color: var(--amber);
  background: var(--amber-bg);
  border-color: rgba(160, 96, 8, 0.3);
}

.chip.bad {
  color: var(--rust);
  background: var(--rust-bg);
  border-color: rgba(166, 61, 50, 0.3);
}

.chip.mono,
.chip code {
  font-family: var(--mono);
  font-weight: 450;
}

/* --- provenance stamp: every claim names its source --- */

.provenance {
  font-size: 11.5px;
  color: var(--faint);
  margin-top: 10px;
}

.provenance code {
  color: var(--muted);
  background: none;
  padding: 0;
}

/* --- totals strip --- */

.totals {
  display: flex;
  gap: 28px;
  padding: 16px 20px;
  background: var(--card);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.totals .figure {
  font-family: var(--display);
  font-size: 26px;
  font-weight: 520;
  line-height: 1.1;
}

.totals .figure.warn {
  color: var(--amber);
}

.totals .figure.bad {
  color: var(--rust);
}

.totals .label {
  font-size: 11.5px;
  color: var(--muted);
}

/* --- environment ladder --- */

.ladder {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.ladder .rung {
  font-family: var(--mono);
  font-size: 11px;
  border: 1px solid var(--hairline);
  border-radius: 6px;
  padding: 2px 8px;
  background: var(--card);
  color: var(--muted);
}

.ladder .rung strong {
  color: var(--ink);
  font-weight: 600;
}

.ladder .rung.pending {
  border-color: rgba(160, 96, 8, 0.4);
  background: var(--amber-bg);
}

.ladder .rung.behind {
  border-color: rgba(166, 61, 50, 0.4);
  background: var(--rust-bg);
}

.ladder .arrow {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 11px;
}

/* --- fingerprint glyph --- */

.glyph {
  display: inline-block;
  vertical-align: middle;
  border-radius: 4px;
  flex: none;
}

.fp {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--muted);
}

/* --- command line rendering (the portal never acts) --- */

.command {
  font-family: var(--mono);
  font-size: 12.5px;
  background: #223236;
  color: #d7e5e0;
  border-radius: 8px;
  padding: 10px 14px;
  overflow-x: auto;
  white-space: pre;
}

.command::before {
  content: '$ ';
  color: #7ba296;
}

/* --- schema tree --- */

.schema-tree {
  font-family: var(--mono);
  font-size: 12.5px;
  line-height: 1.9;
}

.schema-tree .field-type {
  color: var(--verdigris-deep);
}

.schema-tree .field-req {
  color: var(--amber);
  font-size: 10.5px;
  margin-left: 6px;
}

.schema-tree ul {
  list-style: none;
  margin: 0;
  padding-left: 18px;
  border-left: 1px solid var(--hairline);
}

.schema-tree > ul {
  border-left: none;
  padding-left: 0;
}

/* --- ledger --- */

.ledger-day {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 560;
  color: var(--muted);
  margin: 26px 0 8px;
}

.fact-row {
  display: grid;
  grid-template-columns: 52px 148px 1fr auto;
  gap: 14px;
  padding: 9px 14px;
  border-bottom: 1px solid var(--hairline);
  align-items: baseline;
}

.fact-row:hover {
  background: rgba(42, 122, 104, 0.035);
}

.fact-row .at {
  font-family: var(--mono);
  font-size: 11.5px;
  color: var(--faint);
}

.fact-row .subject {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.fact-row .what {
  min-width: 0;
}

.fact-row .stamp {
  font-size: 11px;
  color: var(--faint);
  white-space: nowrap;
}

.filters {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
}

.filters select {
  font-family: var(--body);
  font-size: 13px;
  padding: 6px 10px;
  border: 1px solid var(--hairline);
  border-radius: 8px;
  background: var(--card);
  color: var(--ink);
}

/* --- drift + attention panels --- */

.panel {
  border-radius: 10px;
  padding: 14px 18px;
  border: 1px solid;
}

.panel.warn {
  background: var(--amber-bg);
  border-color: rgba(160, 96, 8, 0.35);
}

.panel.bad {
  background: var(--rust-bg);
  border-color: rgba(166, 61, 50, 0.35);
}

.panel h3 {
  margin-top: 0;
}

/* --- map --- */

.map-wrap {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 20px;
  align-items: start;
}

.map-canvas {
  height: 560px;
  background: var(--card);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  overflow: hidden;
}

.map-node {
  border: 1.5px solid var(--ink);
  border-radius: 10px;
  background: var(--card);
  padding: 10px 14px;
  font-size: 12.5px;
  min-width: 148px;
}

.map-node .eyebrow {
  margin-bottom: 2px;
}

.map-node .name {
  font-weight: 650;
  font-size: 13.5px;
}

.map-node.external {
  border-style: solid;
  border-color: var(--faint);
  border-radius: 999px;
  background: var(--paper);
  text-align: center;
  min-width: 110px;
}

.map-node .badges {
  display: flex;
  gap: 4px;
  margin-top: 6px;
  flex-wrap: wrap;
}

.legend {
  display: flex;
  gap: 18px;
  margin-top: 12px;
  font-size: 12px;
  color: var(--muted);
  flex-wrap: wrap;
}

.legend .swatch {
  display: inline-block;
  width: 26px;
  height: 0;
  border-top: 2px solid var(--ink);
  vertical-align: middle;
  margin-right: 6px;
}

.legend .swatch.mediated {
  border-top-color: var(--verdigris);
}

.legend .swatch.derived {
  border-top-style: dashed;
  border-top-color: var(--amber);
}

/* --- knowledge --- */

.doc-card {
  background: var(--card);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  padding: 22px 26px;
  margin-bottom: 20px;
  max-width: 760px;
}

.doc-card p {
  max-width: 66ch;
}

.triage {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  margin-top: 10px;
}

.triage th,
.triage td {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--hairline);
  vertical-align: top;
}

.triage th {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
}

/* --- misc --- */

.row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 12px;
}

.empty {
  color: var(--muted);
  padding: 32px;
  text-align: center;
  border: 1px dashed var(--hairline);
  border-radius: 10px;
}

.summary-sentence {
  color: var(--muted);
  font-size: 13px;
}

.external-link::after {
  content: ' ↗';
  font-size: 11px;
}

@media (max-width: 900px) {
  .shell {
    grid-template-columns: 1fr;
  }

  .rail {
    position: static;
    height: auto;
    flex-direction: row;
    align-items: center;
    flex-wrap: wrap;
    border-right: none;
    border-bottom: 1px solid var(--hairline);
  }

  .rail nav {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .rail-foot {
    display: none;
  }

  main.content {
    padding: 24px 20px 60px;
  }

  .grid-2,
  .map-wrap {
    grid-template-columns: 1fr;
  }

  .fact-row {
    grid-template-columns: 52px 1fr;
  }

  .fact-row .stamp {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

