import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'
import type { SystemNeighbor, SystemsTableRow } from '../data/source'
import { monitoringLink } from '../fixtures/knowledge'
import { EnvLadder, Provenance, fmtTime } from '../components/shared'

function NeighborList({ neighbors }: { neighbors: SystemNeighbor[] }) {
  if (neighbors.length === 0) return <span className="muted small">—</span>
  return (
    <span className="row" style={{ gap: 6 }}>
      {neighbors.map((neighbor) =>
        neighbor.kind === 'system' ? (
          <Link
            key={neighbor.name}
            className="chip"
            to={`/systems/${neighbor.domain}/${neighbor.name}`}
          >
            {neighbor.name}
          </Link>
        ) : (
          <span key={neighbor.name} className="chip">
            {neighbor.name}
          </span>
        ),
      )}
    </span>
  )
}

function distinct(rows: SystemsTableRow[], pick: (row: SystemsTableRow) => string[]): string[] {
  return [...new Set(rows.flatMap(pick))].sort()
}

function SystemsTable({ rows }: { rows: SystemsTableRow[] }) {
  const [name, setName] = useState('')
  const [source, setSource] = useState('')
  const [entity, setEntity] = useState('')
  const [destination, setDestination] = useState('')

  const options = useMemo(
    () => ({
      sources: distinct(rows, (r) => r.sources.map((n) => n.name)),
      entities: distinct(rows, (r) => r.entities),
      destinations: distinct(rows, (r) => r.destinations.map((n) => n.name)),
    }),
    [rows],
  )

  const filtered = rows.filter((row) => {
    if (name && !row.system.toLowerCase().includes(name.toLowerCase())) return false
    if (source && !row.sources.some((n) => n.name === source)) return false
    if (entity && !row.entities.includes(entity)) return false
    if (destination && !row.destinations.some((n) => n.name === destination)) return false
    return true
  })

  return (
    <table className="board systems-table">
      <thead>
        <tr>
          <th>
            system
            <input
              type="search"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="filter"
              aria-label="Filter by system name"
            />
          </th>
          <th>
            source systems
            <select
              value={source}
              onChange={(e) => setSource(e.target.value)}
              aria-label="Filter by source system"
            >
              <option value="">any</option>
              {options.sources.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
          <th>
            entity
            <select
              value={entity}
              onChange={(e) => setEntity(e.target.value)}
              aria-label="Filter by entity"
            >
              <option value="">any</option>
              {options.entities.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
          <th>
            destination systems
            <select
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              aria-label="Filter by destination system"
            >
              <option value="">any</option>
              {options.destinations.map((v) => (
                <option key={v}>{v}</option>
              ))}
            </select>
          </th>
        </tr>
      </thead>
      <tbody>
        {filtered.map((row) => (
          <tr key={row.system}>
            <td>
              <div className="eyebrow">{row.domain}</div>
              <Link to={`/systems/${row.domain}/${row.system}`}>
                <strong>{row.system}</strong>
              </Link>{' '}
              {!row.consistent && <span className="chip bad">disagree</span>}
              {row.pendingGates > 0 && <span className="chip warn">gate</span>}
            </td>
            <td>
              <NeighborList neighbors={row.sources} />
            </td>
            <td>
              <span className="row" style={{ gap: 6 }}>
                {row.entities.map((e) => (
                  <span key={e} className="chip mono">
                    {e}
                  </span>
                ))}
              </span>
            </td>
            <td>
              <NeighborList neighbors={row.destinations} />
            </td>
          </tr>
        ))}
        {filtered.length === 0 && (
          <tr>
            <td colSpan={4}>
              <span className="muted">No system matches this filter. Widen it.</span>
            </td>
          </tr>
        )}
      </tbody>
    </table>
  )
}

export function EstatePage() {
  const estate = useData(() => mockSource.estate())
  const systems = useData(() => mockSource.systemsTable())
  if (!estate || !systems) return null

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">estate · {estate.customer}</div>
        <h1>What we run, and whether it agrees</h1>
        <p className="lede">
          Every row is what <code>deploy status</code> said about one component across every
          environment. The portal renders those sentences as served — it never re-derives them.
        </p>
      </header>

      <div className="totals">
        <div>
          <div className="figure">{estate.totals.systems}</div>
          <div className="label">systems</div>
        </div>
        <div>
          <div className="figure">{estate.totals.components}</div>
          <div className="label">components</div>
        </div>
        <div>
          <div className={`figure${estate.totals.inconsistent > 0 ? ' bad' : ''}`}>
            {estate.totals.inconsistent}
          </div>
          <div className="label">environments disagree</div>
        </div>
        <div>
          <div className={`figure${estate.totals.pendingGates > 0 ? ' warn' : ''}`}>
            {estate.totals.pendingGates}
          </div>
          <div className="label">unspent sync gates</div>
        </div>
        <div style={{ marginLeft: 'auto', alignSelf: 'end' }} className="small muted">
          read {fmtTime(estate.readAt)}
        </div>
      </div>

      {estate.domains.map(({ domain, systems }) => (
        <section key={domain}>
          <h2>{domain}</h2>
          <div className="stack">
            {systems.map((system) => (
              <div key={system.urn} className="card">
                <div className="row" style={{ justifyContent: 'space-between' }}>
                  <h3 style={{ marginBottom: 4 }}>
                    <Link to={`/systems/${system.domain}/${system.system}`}>{system.system}</Link>
                  </h3>
                  <div className="row">
                    {!system.consistent && <span className="chip bad">environments disagree</span>}
                    {system.pendingGates > 0 && (
                      <span className="chip warn">
                        {system.pendingGates} gate{system.pendingGates > 1 ? 's' : ''} awaiting sync
                      </span>
                    )}
                    <a
                      className="chip external-link"
                      href={monitoringLink(system.system)}
                      target="_blank"
                      rel="noreferrer"
                    >
                      monitoring
                    </a>
                  </div>
                </div>
                <table className="board" style={{ border: 'none' }}>
                  <thead>
                    <tr>
                      <th style={{ width: '18%' }}>component</th>
                      <th>environments</th>
                      <th style={{ width: '34%' }}>what deploy status said</th>
                    </tr>
                  </thead>
                  <tbody>
                    {system.components.map((component) => (
                      <tr key={component.urn}>
                        <td>
                          <span className="mono">{component.component}</span>
                        </td>
                        <td>
                          <EnvLadder environments={component.status.environments} />
                        </td>
                        <td>
                          <span className="summary-sentence">{component.status.summary}</span>
                          {component.status.notes?.map((note) => (
                            <div key={note} className="small muted">
                              — {note}
                            </div>
                          ))}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <Provenance
                  source={{ command: 'deploy status', version: '0.9.2', actor: 'reconciler' }}
                  at={system.components[0]?.observedAt ?? estate.readAt}
                />
              </div>
            ))}
          </div>
        </section>
      ))}
    </>
  )
}

