import { useState } from 'react'
import { Command, fmtDay, fmtTime } from '../components/shared'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'
import type {
  ContractChangedPayload,
  Fact,
  GatePayload,
  PinPayload,
  ReleaseManifest,
  ScaffoldRecord,
  SyncPayload,
} from '../domain/types'
import { shortSha, urnPath } from '../domain/urn'
import { FingerprintGlyph } from '../components/FingerprintGlyph'

const KINDS = [
  'release.created',
  'env.pinned',
  'env.promoted',
  'env.synced',
  'gate.pending',
  'contract.changed',
  'component.scaffolded',
]

const SYSTEMS = ['erp-orders', 'webshop-sync', 'invoicing']

function KindChip({ kind }: { kind: string }) {
  const tone = kind === 'gate.pending' ? 'warn' : kind === 'contract.changed' ? 'warn' : ''
  return <span className={`chip mono ${tone}`}>{kind}</span>
}

function FactLine({ fact }: { fact: Fact }) {
  switch (fact.kind) {
    case 'release.created': {
      const p = fact.payload as ReleaseManifest
      return (
        <>
          <span className="mono">
            {p.component} @ {p.version}
          </span>{' '}
          by {p.createdBy} — {(p.changes ?? []).length} change{(p.changes ?? []).length === 1 ? '' : 's'}
          {p.notes ? <span className="muted"> · {p.notes}</span> : null}
        </>
      )
    }
    case 'env.pinned':
    case 'env.promoted': {
      const p = fact.payload as PinPayload
      return (
        <>
          {p.promotedFrom ? (
            <>
              {p.promotedFrom} -&gt; <strong>{p.environment}</strong>
            </>
          ) : (
            <strong>{p.environment}</strong>
          )}{' '}
          <span className="mono">
            {p.component} @ {p.release} ({shortSha(p.digest.replace('sha256:', ''))})
          </span>
        </>
      )
    }
    case 'env.synced': {
      const p = fact.payload as SyncPayload
      return (
        <>
          <strong>{p.environment}</strong> applied{' '}
          <span className="mono">rev {p.revision}</span> · {p.healthStatus}
        </>
      )
    }
    case 'gate.pending': {
      const p = fact.payload as GatePayload
      return (
        <>
          <strong>{p.environment}</strong> holds a committed change for{' '}
          <span className="mono">
            {p.component} @ {p.release}
          </span>{' '}
          — an unspent manual gate, not a fault.
          <div style={{ marginTop: 8, maxWidth: 460 }}>
            <Command>
              intropy deploy sync {p.component} --env {p.environment}
            </Command>
          </div>
        </>
      )
    }
    case 'contract.changed': {
      const p = fact.payload as ContractChangedPayload
      return (
        <span className="row" style={{ gap: 6 }}>
          <span className="mono">{p.shortName}</span>
          <FingerprintGlyph fingerprint={p.from} size={14} />
          <span className="fp">{p.from}</span>
          <span className="mono">-&gt;</span>
          <FingerprintGlyph fingerprint={p.to} size={14} />
          <span className="fp">{p.to}</span>
          <span className="muted small">
            with {p.component} @ {p.release}
          </span>
        </span>
      )
    }
    case 'component.scaffolded': {
      const p = fact.payload as ScaffoldRecord
      return (
        <>
          scaffolded from template <span className="mono">{p.template}</span>
          {p.blockKind ? <span className="muted"> · {p.blockKind}</span> : null}
        </>
      )
    }
    default:
      return <span className="muted">{fact.kind}</span>
  }
}

export function LedgerPage() {
  const [kind, setKind] = useState('')
  const [system, setSystem] = useState('')
  const facts = useData(
    () => mockSource.ledger({ kind: kind || undefined, system: system || undefined }),
    [kind, system],
  )
  if (!facts) return null

  const byDay = new Map<string, Fact[]>()
  for (const fact of facts) {
    const day = fact.observedAt.slice(0, 10)
    byDay.set(day, [...(byDay.get(day) ?? []), fact])
  }

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">ledger</div>
        <h1>What changed, when, by whom</h1>
        <p className="lede">
          Releases, pins, promotions, and syncs across the estate, in the order they were
          observed. Every entry is a fact its source already records — GitOps trailers, release
          manifests, ArgoCD.
        </p>
      </header>

      <div className="filters">
        <select value={kind} onChange={(e) => setKind(e.target.value)} aria-label="Filter by kind">
          <option value="">every kind</option>
          {KINDS.map((k) => (
            <option key={k} value={k}>
              {k}
            </option>
          ))}
        </select>
        <select
          value={system}
          onChange={(e) => setSystem(e.target.value)}
          aria-label="Filter by system"
        >
          <option value="">every system</option>
          {SYSTEMS.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
      </div>

      {facts.length === 0 && (
        <div className="empty">No facts match this filter. Widen it to see the estate move.</div>
      )}

      {[...byDay.entries()].map(([day, dayFacts]) => (
        <section key={day}>
          <div className="ledger-day">{fmtDay(day)}</div>
          <div className="card" style={{ padding: 0 }}>
            {dayFacts.map((fact) => (
              <div key={fact.id} className="fact-row">
                <span className="at">{fmtTime(fact.observedAt).slice(-5)}</span>
                <span>
                  <KindChip kind={fact.kind} />
                </span>
                <span className="what">
                  <div className="subject">{urnPath(fact.urn)}</div>
                  <FactLine fact={fact} />
                </span>
                <span className="stamp">
                  <code>{fact.source.command}</code>
                  {fact.source.actor ? ` · ${fact.source.actor}` : ''}
                </span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </>
  )
}

import { useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Background,
  Handle,
  Position,
  ReactFlow,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { mockSource } from '../data/mock'
import { useData } from '../data/useData'
import type { MapNode } from '../data/source'
import { SYSTEM_DOMAIN } from '../fixtures/topologies'

// Persisted stable layout: the map is the same place every day. Real
// ingestion would store anchors; the PoC states them.
const POSITIONS: Record<string, { x: number; y: number }> = {
  'erp-orders': { x: 260, y: 20 },
  'webshop-sync': { x: 260, y: 380 },
  invoicing: { x: 600, y: 170 },
  'ext:SAP ECC': { x: 10, y: 190 },
  'ext:Storefront': { x: 580, y: 460 },
  'ext:Visma eEkonomi': { x: 850, y: 260 },
}

type FlowNode = Node<{ node: MapNode }>

function SystemNode({ data }: NodeProps<FlowNode>) {
  const { node } = data
  return (
    <div className="map-node">
      <Handle type="target" position={Position.Left} style={{ opacity: 0 }} />
      <div className="eyebrow">{node.domain}</div>
      <div className="name">{node.label}</div>
      <div className="badges">
        {node.consistent === false && <span className="chip bad">disagree</span>}
        {(node.pendingGates ?? 0) > 0 && <span className="chip warn">gate</span>}
        {node.drift && <span className="chip warn">{node.drift}</span>}
      </div>
      <Handle type="source" position={Position.Right} style={{ opacity: 0 }} />
    </div>
  )
}

function ExternalNode({ data }: NodeProps<FlowNode>) {
  const { node } = data
  return (
    <div className="map-node external">
      <Handle type="target" position={Position.Left} style={{ opacity: 0 }} />
      <div className="name">{node.label}</div>
      <Handle type="source" position={Position.Right} style={{ opacity: 0 }} />
    </div>
  )
}

const nodeTypes = { system: SystemNode, external: ExternalNode }

const EDGE_STYLE = {
  declared: { stroke: '#1d2a2e', strokeWidth: 1.5 },
  mediated: { stroke: '#2a7a68', strokeWidth: 1.5 },
  derived: { stroke: '#a06008', strokeWidth: 1.5, strokeDasharray: '6 5' },
} as const

export function MapPage() {
  const graph = useData(() => mockSource.map())
  const navigate = useNavigate()

  const { nodes, edges } = useMemo(() => {
    if (!graph) return { nodes: [] as FlowNode[], edges: [] as Edge[] }
    const nodes: FlowNode[] = graph.nodes.map((node) => ({
      id: node.id,
      type: node.kind,
      position: POSITIONS[node.id] ?? { x: 100, y: 100 },
      data: { node },
    }))
    const edges: Edge[] = graph.edges.map((edge) => ({
      id: edge.id,
      source: edge.from,
      target: edge.to,
      label: edge.label,
      type: 'default',
      style: EDGE_STYLE[edge.provenance],
      labelStyle: { fontSize: 10, fill: '#5d6f6e', fontFamily: 'IBM Plex Mono, monospace' },
      labelBgStyle: { fill: '#fbfcfb', fillOpacity: 0.9 },
      animated: edge.provenance === 'derived',
    }))
    return { nodes, edges }
  }, [graph])

  if (!graph) return null

  return (
    <>
      <header className="page-head">
        <div className="eyebrow">landscape map · render-only</div>
        <h1>The estate, as declared</h1>
        <p className="lede">
          Every edge comes from a declared topology or a provable join — the map never invents
          wiring. Intent stays in the diagramming tool; what it drew and reality disagree on shows
          up here as drift.
        </p>
      </header>

      <div className="map-wrap">
        <div>
          <div className="map-canvas">
            <ReactFlow
              nodes={nodes}
              edges={edges}
              nodeTypes={nodeTypes}
              fitView
              nodesDraggable={false}
              nodesConnectable={false}
              proOptions={{ hideAttribution: true }}
              onNodeClick={(_, node) => {
                const mapNode = (node.data as { node: MapNode }).node
                if (mapNode.kind === 'system') {
                  navigate(`/systems/${SYSTEM_DOMAIN[mapNode.id] ?? 'commerce'}/${mapNode.id}`)
                }
              }}
            >
              <Background gap={24} color="#dde6e3" />
            </ReactFlow>
          </div>
          <div className="legend">
            <span>
              <span className="swatch" /> declared connector
            </span>
            <span>
              <span className="swatch mediated" /> mediated by a shared external system
            </span>
            <span>
              <span className="swatch derived" /> derived: same shape (fingerprint equality)
            </span>
          </div>
        </div>

        <aside className="card">
          <h3>Diagram bindings</h3>
          <p className="small muted" style={{ marginTop: 0 }}>
            What the diagramming tool's shapes are bound to, and whether reality still agrees.
          </p>
          {graph.bindings.map((binding) => (
            <div key={binding.shape} style={{ marginBottom: 12 }}>
              <div className="row" style={{ gap: 8 }}>
                <span
                  className={`chip ${
                    binding.state === 'live' ? 'ok' : binding.state === 'stale' ? 'bad' : 'warn'
                  }`}
                >
                  {binding.state}
                </span>
                <strong className="small">{binding.shape}</strong>
              </div>
              <div className="small muted">{binding.diagram}</div>
              {binding.note && <div className="small muted">— {binding.note}</div>}
            </div>
          ))}
          <a
            className="chip external-link"
            href="https://diagrams.acme.example/order-flow-overview"
            target="_blank"
            rel="noreferrer"
          >
            open diagram
          </a>
        </aside>
      </div>
    </>
  )
}

