    expect(webshop?.sources.map((n) => n.name).sort()).toEqual(['Storefront', 'erp-orders'])
    expect(webshop?.sources.find((n) => n.name === 'erp-orders')?.kind).toBe('system')
    expect(webshop?.destinations.map((n) => n.name).sort()).toEqual(['SAP ECC', 'Storefront'])
  })

  it('lists the shapes a system speaks as its entities', () => {
    expect(bySystem.get('invoicing')?.entities).toEqual(['InvoiceCreated', 'OrderConfirmed'])
    expect(bySystem.get('erp-orders')?.entities).toEqual(['OrderConfirmed', 'OrderRaw'])
  })

  it('derives downstream systems for the publisher', () => {
    const erp = bySystem.get('erp-orders')
    expect(erp?.destinations.map((n) => n.name).sort()).toEqual(['invoicing', 'webshop-sync'])
